#!/bin/bash
# 曦微博客手动部署包 v1.3.22
# 用法: curl -sL https://raw.githubusercontent.com/yangxivi/XiviBlog/deploy/install.sh | bash
# 在 192.144.159.110 上以 root 执行

set -e
BLOG_DIR=/www/wwwroot/xiviblog
mkdir -p $BLOG_DIR/backups $BLOG_DIR/scripts

echo '=== 曦微博客手动部署 ==='

# 1. 写入 middleware.ts（安装闸门 + 登录保护）
echo  | base64 -d > $BLOG_DIR/selfhosted/middleware.ts
echo 'OK middleware.ts ($(wc -c < $BLOG_DIR/selfhosted/middleware.ts) bytes)'

# 2. 写入 self-update.cjs（v1.3.22 预构建更新脚本）
echo  | base64 -d > $BLOG_DIR/scripts/self-update.cjs
echo 'OK self-update.cjs ($(wc -c < $BLOG_DIR/scripts/self-update.cjs) bytes)'

# 3. 写入 deploy-manual.sh（完整部署脚本）
echo  | base64 -d > $BLOG_DIR/deploy-manual.sh
echo 'OK deploy-manual.sh ($(wc -c < $BLOG_DIR/deploy-manual.sh) bytes)'

# 4. 执行部署（备份 + 构建 + 重启，约 5-10 分钟）
bash $BLOG_DIR/deploy-manual.sh

# 5. 验证
echo '=== 验证 ==='
curl -I http://127.0.0.1:3000/install 2>&1 | head -5
pm2 status xiviblog 2>&1 | head -5
